function busquedaAceptable({valor:valor,tocado:tocado,esInputEvent:esInputEvent,emailSesion:emailSesion}){const v=String(valor==null?"":valor).trim().toLowerCase();if(!v)return true;const yo=String(emailSesion||"").trim().toLowerCase();if(yo&&v===yo)return false;if(!tocado&&!esInputEvent)return false;return true}function lwBlindarBuscador(input,{email:email,alCambiar:alCambiar}){if(!input)return{barrer(){}};let tocado=false;["keydown","paste","drop","cut","compositionstart"].forEach((t=>input.addEventListener(t,(()=>{tocado=true}))));const rechazar=()=>{input.value="";alCambiar("")};input.addEventListener("input",(ev=>{const ok=busquedaAceptable({valor:input.value,tocado:tocado,esInputEvent:typeof InputEvent!=="undefined"&&ev instanceof InputEvent,emailSesion:email()});if(ok)alCambiar(input.value);else rechazar()}));input.addEventListener("animationstart",(ev=>{if(ev.animationName==="lw-autorrelleno"&&!tocado)rechazar()}));return{barrer(){if(input.value&&!busquedaAceptable({valor:input.value,tocado:tocado,esInputEvent:false,emailSesion:email()}))rechazar()}}}if(typeof module!=="undefined")module.exports={busquedaAceptable:busquedaAceptable};